import { useState } from "react";
import { useApp } from "../context/AppContext";

const roller = [
  { key: "kamyoncu", icon: "🚛", baslik: "Kamyoncu", aciklama: "İlanları gör, teklif ver, sefer yönet", renk: "var(--turuncu)" },
  { key: "issiz",    icon: "🏢", baslik: "İş Veren",  aciklama: "İlan ver, teklif al, kamyon bul",      renk: "var(--sari)" },
  { key: "admin",    icon: "⚙️", baslik: "Admin",      aciklama: "Platformu yönet, her şeye eriş",       renk: "var(--mavi)" },
];

export default function GirisEkrani() {
  const { girisYap } = useApp();
  const [adim, setAdim]     = useState(1);
  const [secRol, setSecRol] = useState(null);
  const [ad, setAd]         = useState("");
  const [loading, setLoading] = useState(false);

  const secRole = (r) => { setSecRol(r); setAdim(2); };

  const giris = () => {
    if (!ad.trim()) return;
    setLoading(true);
    setTimeout(() => girisYap(secRol, ad.trim()), 800);
  };

  return (
    <div style={{ minHeight: "100vh", background: "var(--bg)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 24, position: "relative", overflow: "hidden" }}>
      {/* Arkaplan efekti */}
      <div style={{ position: "absolute", top: -100, left: -100, width: 400, height: 400, background: "radial-gradient(circle, rgba(232,82,10,0.08) 0%, transparent 70%)", pointerEvents: "none" }} />
      <div style={{ position: "absolute", bottom: -80, right: -80, width: 300, height: 300, background: "radial-gradient(circle, rgba(245,166,35,0.06) 0%, transparent 70%)", pointerEvents: "none" }} />

      <div style={{ width: "100%", maxWidth: 400, animation: "slideDown 0.4s ease" }}>
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: 48 }}>
          <div style={{ fontFamily: "var(--font-d)", fontSize: 58, letterSpacing: 5, lineHeight: 1, marginBottom: 8 }}>
            NAKLI<span style={{ color: "var(--turuncu)" }}>YOL</span>
          </div>
          <div style={{ fontSize: 12, color: "var(--text3)", letterSpacing: 2, textTransform: "uppercase" }}>
            Türkiye'nin Kamyon Platformu
          </div>
        </div>

        {adim === 1 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <div className="label" style={{ textAlign: "center", marginBottom: 8 }}>Rolünü seç</div>
            {roller.map(r => (
              <button key={r.key} onClick={() => secRole(r.key)} style={{
                background: "var(--bg1)", border: "1px solid var(--border)",
                borderRadius: "var(--r-lg)", padding: "18px 20px",
                display: "flex", alignItems: "center", gap: 16,
                cursor: "pointer", transition: "var(--tr)", color: "var(--text)",
                textAlign: "left", width: "100%",
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = r.renk; e.currentTarget.style.background = "var(--bg2)"; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = "var(--border)"; e.currentTarget.style.background = "var(--bg1)"; }}
              >
                <span style={{ fontSize: 34 }}>{r.icon}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "var(--font-d)", fontSize: 20, letterSpacing: 1, color: r.renk }}>{r.baslik}</div>
                  <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>{r.aciklama}</div>
                </div>
                <span style={{ color: "var(--text3)", fontSize: 18 }}>›</span>
              </button>
            ))}
          </div>
        )}

        {adim === 2 && (
          <div style={{ animation: "slideDown 0.25s ease" }}>
            <button onClick={() => setAdim(1)} style={{ color: "var(--text3)", fontSize: 13, marginBottom: 20, display: "flex", alignItems: "center", gap: 6 }}>← Geri</button>
            <div className="card" style={{ padding: 24 }}>
              <div style={{ fontFamily: "var(--font-d)", fontSize: 26, letterSpacing: 1, color: roller.find(r=>r.key===secRol)?.renk, marginBottom: 4 }}>
                {roller.find(r=>r.key===secRol)?.baslik} Girişi
              </div>
              <div className="label" style={{ marginBottom: 20 }}>Demo mod — adınızı girin</div>

              <div className="input-group">
                <label className="label">Ad Soyad</label>
                <input
                  className="input"
                  placeholder="Mehmet Yılmaz"
                  value={ad}
                  onChange={e => setAd(e.target.value)}
                  onKeyDown={e => e.key === "Enter" && giris()}
                  autoFocus
                />
              </div>

              <button
                onClick={giris}
                disabled={!ad.trim() || loading}
                className="btn btn-primary btn-display btn-full"
                style={{ marginTop: 8 }}
              >
                {loading ? "GİRİYOR..." : "GİRİŞ YAP"}
              </button>
            </div>
          </div>
        )}

        <div style={{ textAlign: "center", marginTop: 32, fontSize: 11, color: "var(--text3)" }}>
          NakliYol © 2026 — Tüm hakları saklıdır
        </div>
      </div>
    </div>
  );
}
